<?php $pageTitle='Customer Register'; require_once __DIR__ . '/../includes/header.php'; if($_SERVER['REQUEST_METHOD']==='POST'){ $name=trim($_POST['name']); $email=trim($_POST['email']); $password=password_hash($_POST['password'], PASSWORD_DEFAULT); if($name && $email && $_POST['password']){ $stmt=db()->prepare('INSERT INTO customers (name, email, password) VALUES (?, ?, ?)'); $stmt->execute([$name,$email,$password]); set_flash('success','Registration successful.'); redirect('/car-rent-sale-system/auth/login.php'); }} ?><div class="container py-5"><div class="row justify-content-center"><div class="col-md-6"><div class="form-box"><h2 class="section-title">Customer Register</h2><form method="post"><div class="mb-3"><input class="form-control" name="name" placeholder="Full Name" required></div><div class="mb-3"><input type="email" class="form-control" name="email" placeholder="Email" required></div><div class="mb-3"><input type="password" class="form-control" name="password" placeholder="Password" required></div><button class="btn btn-primary">Register</button></form></div></div></div></div><?php require_once __DIR__ . '/../includes/footer.php'; ?>
